const PIT_CAM_ENTER_DIST = 20;
const PIT_CAM_EXIT_DIST = 11;

function pitCameraWanted() {
  if (!race || race.state === 'finished' || race.state === 'paused') return false;
  const pit = race.pit;
  const { boxDistance } = pitMetrics();
  if (pit.phase === 'servicing') return true;
  if (pit.phase === 'driving-in') {
    const remaining = boxDistance - pit.routeProgress;
    return remaining <= PIT_CAM_ENTER_DIST;
  }
  if (pit.phase === 'driving-out') {
    return pit.routeProgress - boxDistance <= PIT_CAM_EXIT_DIST;
  }
  return false;
}

function pitBoxCameraShot() {
  const box = race.world.playerPitBox;
  const yaw = box.yaw;
  const fx = Math.sin(yaw), fz = Math.cos(yaw);
  const lx = Math.cos(yaw), lz = -Math.sin(yaw);
  const ahead = 0.9, towardGarage = 0.6, back = 0.8, height = 20.5;
  const position = camVecPitA.set(
     box.x + lx * (-6.4) + fx * (-back),
     height,
     box.z + lz * (-6.4) + fz * (-back)
  );
  const target = camVecPitB.set(
     box.x + lx * towardGarage + fx * ahead,
     0.45,
     box.z + lz * towardGarage + fz * ahead
  );
  return { position, target, fov: 33 };
