import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
import { readFileSync, mkdirSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY == null) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const outDir = '/tmp/opencode/shots';
mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch(launchOptions);

async function run(label, viewport, isMobile) {
  const context = await browser.newContext({ viewport, screen: viewport, isMobile, hasTouch: isMobile, deviceScaleFactor: 1 });
  const page = await context.newPage();
  page.on('pageerror', (e) => console.log(label, 'PAGEERROR', e.message));
  await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
  await page.waitForTimeout(800);

  // Put the car 10 m short of its box, on the pit approach, and let the game drive it in.
  await page.evaluate(() => {
    const r = window.__apex.race;
    const boxDist = r.world.pitBoxDistance;
    const d = boxDist - 10;
    const route = r.world.pitRoute;
    const i = Math.min(route.length - 2, Math.floor(d / 5));
    const t = d / 5 - i;
    const a = route[i], b = route[i + 1];
    const x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
    let tx = a.tx + (b.tx - a.tx) * t, tz = a.tz + (b.tz - a.tz) * t;
    const len = Math.hypot(tx, tz) || 1;
    tx /= len; tz /= len;
    const yaw = Math.atan2(tx, tz);
    const remaining = 10;
    const k = Math.min(1, remaining / 36);
    const smooth = k * k * (3 - 2 * k);
    const offset = r.world.pitBoxLateral * (1 - smooth);
    const px = x + Math.cos(yaw) * offset;
    const pz = z - Math.sin(yaw) * offset;
    r.pit.phase = 'driving-in';
    r.pit.serviceTimer = 0;
    r.pit.routeProgress = d;
    r.pit.entryProgress = 0;
    r.player.progressDist = d;
    r.player.pos.x = px;
    r.player.pos.z = pz;
    r.player.yaw = yaw;
    r.player.vel.x = 0; r.player.vel.z = 0; r.player.vLong = 0;
    r.player.lastIndex = r.locator.lastIndex;
  });

  await page.waitForFunction(() => window.__apex.race.pitCamBlend > 0.9, null, { timeout: 20000 });
  await page.screenshot({ path: join(outDir, `${label}-approach.jpg`), type: 'jpeg', quality: 78 });
  console.log(label, 'approach', await page.evaluate(() => ({
    phase: __apex.race.pit.phase,
    route: +__apex.race.pit.routeProgress.toFixed(1),
    blend: +__apex.race.pitCamBlend.toFixed(3),
    camY: +__apex.race.camera.position.y.toFixed(2),
    cam: __apex.race.camera.position.toArray().map((n) => +n.toFixed(2)),
    car: [__apex.race.player.pos.x, __apex.race.player.pos.z].map((n) => +n.toFixed(2))
  })));

  // Force the stop so the car is parked on its marks beneath the fixed camera.
  await page.evaluate(() => {
    const r = window.__apex.race;
    r.pit.phase = 'servicing';
    r.pit.serviceDuration = 999;
    r.pit.serviceTimer = 999;
  });
  await page.waitForFunction(() => window.__apex.race.camera.position.y > (window.innerWidth / window.innerHeight < 1 ? 18.8 : 17.8), null, { timeout: 20000 });
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(outDir, `${label}-box.jpg`), type: 'jpeg', quality: 80 });
  console.log(label, 'box', await page.evaluate(() => ({
    blend: +__apex.race.pitCamBlend.toFixed(3),
    camY: +__apex.race.camera.position.y.toFixed(2),
    fov: +__apex.race.camera.fov.toFixed(1)
  })));

  // Off the box and away: shot must release back to the chase camera.
  await page.evaluate(() => {
    const r = window.__apex.race;
    r.pit.phase = 'driving-out';
    r.pit.routeProgress = r.world.pitBoxDistance + 14;
    r.pit.serviceTimer = 0;
    r.player.vLong = 18;
  });
  await page.waitForFunction(() => window.__apex.race.pitCamBlend < 0.05, null, { timeout: 20000 });
  await page.screenshot({ path: join(outDir, `${label}-released.jpg`), type: 'jpeg', quality: 78 });
  console.log(label, 'released', await page.evaluate(() => ({
    phase: __apex.race.pit.phase,
    blend: +__apex.race.pitCamBlend.toFixed(3),
    camY: +__apex.race.camera.position.y.toFixed(2)
  })));

  await context.close();
}

await run('desk', { width: 1280, height: 720 }, false);
await run('mob', { width: 430, height: 900 }, true);
await browser.close();

