```
function updatePitDock(dt, p) {
  const pit = race.pit;
  const box = race.world.playerPitBox;
  const { boxDistance } = pitMetrics();
  pit.dockT += dt;
  const dx = box.x - p.pos.x, dz = box.z - p.pos.z;
  const dist = Math.hypot(dx, dz);
  const prevX = p.pos.x, prevZ = p.pos.z;

  // Rate chosen so the initial closing speed matches the car's real speed:
  // the approach then eases in asymptotically and cannot overshoot.
  const rate = clamp(Math.max(0, p.vLong) / Math.max(dist, 0.4), 0.5, 2.2);
  const e = 1 - Math.exp(-rate * dt);
  p.pos.x += dx * e;
  p.pos.z += dz * e;
  const travelYaw = Math.atan2(box.x - p.pos.x, box.z - p.pos.z); // direction still to go
  // align to the box heading as we get close
  const close = 1 - clamp(Math.hypot(box.x - p.pos.x, box.z - p.pos.z) / Math.max(1, pit.dockStartDist), 0, 1);
  let targetYaw = box.yaw;
  if (close < 1) {
    const delta = Math.atan2(Math.sin(travelYaw - box.yaw), Math.cos(travelYaw - box.yaw));
    targetYaw = box.yaw + delta * (1 - close);
  }
  p.yaw = dampAngle(p.yaw, targetYaw, 5.5, dt);
  ...
}
```
