    recoverPlayer(false);
    toast('Reset to the racing line');
  }
});

window.addEventListener('keyup', (e) => {
  if (setKey(e.code, false) && appState === 'race') e.preventDefault();
});

window.addEventListener('blur', () => {
  for (const k of Object.keys(input)) input[k] = false;
