import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY == null) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 900, height: 560 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
await page.waitForTimeout(400);

const setup = await page.evaluate(() => {
  const r = window.__apex.race;
  const boxDist = r.world.pitBoxDistance;
  const d = boxDist - 30;
  const route = r.world.pitRoute;
  const i = Math.min(route.length - 2, Math.floor(d / 5));
  const t = d / 5 - i;
  const a = route[i], b = route[i + 1];
  const x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
  let tx = a.tx + (b.tx - a.tx) * t, tz = a.tz + (b.tz - a.tz) * t;
  const len = Math.hypot(tx, tz) || 1;
  tx /= len; tz /= len;
  const yaw = Math.atan2(tx, tz);
  r.pit.phase = 'driving-in';
  r.pit.routeProgress = d;
  r.pit.entryProgress = 0;
  r.player.progressDist = d;
  r.player.pos.x = x; r.player.pos.z = z;
  r.player.yaw = yaw;
  r.player.vel.x = tx * 5; r.player.vel.z = tz * 5; r.player.vLong = 5;
  r.player.lastIndex = r.locator.lastIndex;
  for (let f = 0; f < 60 * 14; f++) {
    if (r.pit.phase !== 'driving-in') break;
    window.__apex.tick(1 / 60);
  }
  return {
