})));
await page.screenshot({ path: '/tmp/opencode/shots/pit-mini-3.jpg', type: 'jpeg', quality: 80 });

const release = await page.evaluate(() => {
  const r = window.__apex.race;
  for (let f = 0; f < 60 * 3; f++) {
    if (r.pit.phase !== 'servicing') break;
    window.__apex.tick(1 / 60);
  }
  const before = {
    phase: r.pit.phase,
    stage: r.pit.serviceStage,
    tyre: +r.player.tyreLife.toFixed(2),
    mini: document.getElementById('pit-mini').classList.contains('show'),
    speed: +Math.hypot(r.player.vel.x, r.player.vel.z).toFixed(2)
  };
  for (let f = 0; f < 60 * 3; f++) window.__apex.tick(1 / 60);
  return { before, after: {
    phase: r.pit.phase,
