const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3010/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
await page.waitForTimeout(300);
const cases = [
  { back: 45, speed: 0, lat: 0, dt: 1 / 60 },
  { back: 10, speed: 8, lat: 0, dt: 1 / 60 },
  { back: 10, speed: 8, lat: -4, dt: 1 / 60 },
  { back: 10, speed: 8, lat: 4, dt: 1 / 60 },
  { back: 25, speed: 18, lat: 2, dt: 1 / 60 },
  { back: 45, speed: 0, lat: 0, dt: 1 / 20 },
  { back: 5, speed: 12, lat: 0, dt: 1 / 20 },
  { back: 1, speed: 6, lat: 3, dt: 1 / 60 },
  { overshoot: true, speed: 6, lat: 0, dt: 1 / 60 }
];
for (const c of cases) {
  const result = await page.evaluate((cfg) => {
    const r = window.__apex.race;
    const box = r.world.playerPitBox;
    const boxDist = r.world.pitBoxDistance;
    const route = r.world.pitRoute;
    const d = boxDist - (cfg.back || 0);
    const i = Math.min(route.length - 2, Math.floor(d / 5));
    const t = d / 5 - i;
    const a = route[i], b = route[i + 1];
    let x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
    let tx = a.tx + (b.tx - a.tx) * t, tz = a.tz + (b.tz - a.tz) * t;
    const len = Math.hypot(tx, tz) || 1;
    tx /= len; tz /= len;
    const yaw = Math.atan2(tx, tz);
    const nx = Math.cos(yaw), nz = -Math.sin(yaw);
    if (cfg.overshoot) {
      x = box.x + tx * 1.2;
      z = box.z + tz * 1.2;
    }
    r.pit.phase = 'driving-in';
    r.pit.serviceStage = null;
    r.pit.routeProgress = cfg.overshoot ? boxDist : d;
    r.pit.entryProgress = 0;
    r.player.progressDist = r.pit.routeProgress;
    r.player.pos.x = x + nx * (cfg.lat || 0);
    r.player.pos.z = z + nz * (cfg.lat || 0);
    r.player.yaw = yaw;
    r.player.vel.x = tx * cfg.speed; r.player.vel.z = tz * cfg.speed; r.player.vLong = cfg.speed;
    r.player.vLat = 0; r.player.yawRate = 0;
    r.player.lastIndex = r.locator.lastIndex;
    let frames = 0;
    for (; frames < 60 * 24; frames++) {
      if (r.pit.phase !== 'driving-in') break;
      window.__apex.tick(cfg.dt);
    }
    return {
      cfg: cfg.back != null ? `${cfg.back}m @${cfg.speed} lat${cfg.lat} dt${cfg.dt.toFixed(3)}` : `overshoot @${cfg.speed}`,
      phase: r.pit.phase,
      frames,
      route: +r.pit.routeProgress.toFixed(2),
      boxDist: +boxDist.toFixed(2),
      dist: +Math.hypot(r.player.pos.x - box.x, r.player.pos.z - box.z).toFixed(2),
      speed: +Math.hypot(r.player.vel.x, r.player.vel.z).toFixed(2)
    };
  }, c);
  console.log(result);
}
console.log('ERRORS', errors);
await browser.close();
EOF
