import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY == null) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 640, height: 360 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3010/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
await page.waitForTimeout(400);
await page.evaluate(() => {
  const r = window.__apex.race;
  const boxDist = r.world.pitBoxDistance;
  const d = boxDist - 45;
  const route = r.world.pitRoute;
  const i = Math.min(route.length - 2, Math.floor(d / 5));
  const t = d / 5 - i;
  const a = route[i], b = route[i + 1];
  const x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
  let tx = a.tx + (b.tx - a.tx) * t, tz = a.tz + (b.tz - a.tz) * t;
  const len = Math.hypot(tx, tz) || 1;
  tx /= len; tz /= len;
  r.pit.phase = 'driving-in';
  r.pit.routeProgress = d;
  r.pit.entryProgress = 0;
  r.player.progressDist = d;
  r.player.pos.x = x; r.player.pos.z = z;
  r.player.yaw = Math.atan2(tx, tz);
  r.player.vel.x = 0; r.player.vel.z = 0; r.player.vLong = 0;
  r.player.lastIndex = r.locator.lastIndex;
});
let prevPhase = '';
for (let i = 0; i < 160; i++) {
  await page.waitForTimeout(250);
  const s = await page.evaluate(() => {
    const r = window.__apex.race;
    const p = r.player, box = r.world.playerPitBox;
    return {
      phase: r.pit.phase,
      route: +r.pit.routeProgress.toFixed(2),
      v: +p.vLong.toFixed(2),
      dist: +Math.hypot(p.pos.x - box.x, p.pos.z - box.z).toFixed(2),
      mini: document.getElementById('pit-mini').classList.contains('show')
    };
  });
  if (i % 4 === 0 || s.phase !== prevPhase) console.log(s);
  prevPhase = s.phase;
  if (s.phase === 'servicing') break;
}
console.log('SERVICE', await page.evaluate(() => ({
  stage: window.__apex.race.pit.serviceStage,
  title: document.getElementById('pit-mini-title').textContent,
  route: window.__apex.race.pit.routeProgress,
  dist: Math.hypot(window.__apex.race.player.pos.x - window.__apex.race.world.playerPitBox.x, window.__apex.race.player.pos.z - window.__apex.race.world.playerPitBox.z)
})));
// Let time pass: the car must stay parked and the stop must wait for taps.
await page.waitForTimeout(2500);
console.log('WAITED (must still be servicing)', await page.evaluate(() => ({
  phase: window.__apex.race.pit.phase,
  stage: window.__apex.race.pit.serviceStage,
  dist: Math.hypot(window.__apex.race.player.pos.x - window.__apex.race.world.playerPitBox.x, window.__apex.race.player.pos.z - window.__apex.race.world.playerPitBox.z)
})));
await page.click('#pit-mini-hit');
await page.waitForTimeout(200);
await page.click('#pit-mini-hit');
await page.waitForTimeout(1400);
console.log('AFTER TAPS', await page.evaluate(() => ({
  phase: window.__apex.race.pit.phase,
  stage: window.__apex.race.pit.serviceStage,
  mini: document.getElementById('pit-mini').classList.contains('show'),
  tyre: window.__apex.race.player.tyreLife,
  speed: Math.hypot(window.__apex.race.player.vel.x, window.__apex.race.player.vel.z)
})));
console.log('ERRORS', errors);
await browser.close();
