cd /tmp/opencode && cat > mini-livery-check.mjs <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY == null) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 900, height: 560 } });
await page.goto('http://localhost:3000/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
await page.waitForTimeout(300);
const result = await page.evaluate(() => {
  const r = window.__apex.race;
  const box = r.world.playerPitBox;
  r.pit.phase = 'driving-in';
  r.pit.routeProgress = r.world.pitBoxDistance;
  r.pit.entryProgress = 0;
  r.player.progressDist = r.world.pitBoxDistance;
  r.player.pos.x = box.x; r.player.pos.z = box.z;
  r.player.vel.x = 0; r.player.vel.z = 0; r.player.vLong = 0;
  window.__apex.tick(1 / 60);
  return {
    paint: getComputedStyle(document.getElementById('pit-mini')).getPropertyValue('--pit-paint').trim(),
    fill: getComputedStyle(document.querySelector('.pit-mini-body')).fill,
    carPaint: window.__apex.race.playerCar.root ? 'car' : 'no'
  };
});
console.log(result);
await page.locator('#pit-mini').screenshot({ path: '/tmp/opencode/shots/pit-mini-livery.png' });
await browser.close();
EOF
node mini-livery-check.mjs

