.pit-mini-engine { fill: rgba(10,10,12,.35); }
.pit-mini-nose { fill: rgba(255,255,255,.35); }

/* Every wheel is its own target: the HTML buttons sit over the SVG corners so
   they keep a finger-sized hit area while the car itself stays compact. */
.pit-mini-wheel-btn {
  position: absolute; z-index: 1; width: 46px; height: 46px; margin: 0; padding: 0;
