.pit-mini-wheel-btn[data-wheel="rl"] { left: 19.7%; top: 76%; }
.pit-mini-wheel-btn[data-wheel="rr"] { left: 80.3%; top: 76%; }
.pit-mini-wheel-btn::before {
  content: ""; position: absolute; inset: 5px; border-radius: 50%;
  border: 2px solid transparent; background: transparent;
  opacity: 0; transform: scale(.78);
  transition: opacity .18s, transform .22s var(--ease), background .18s, border-color .18s;
}
.pit-mini[data-stage="remove"] .pit-mini-wheel-btn:not(:disabled)::before,
.pit-mini[data-stage="fit"] .pit-mini-wheel-btn:not(:disabled)::before {
  opacity: 1; transform: scale(1);
  border-color: rgba(var(--wheel-ring), .9);
  background: rgba(var(--wheel-ring), .1);
  animation: pit-wheel-pulse 1.5s infinite;
}
.pit-mini-wheel-btn:not(:disabled):hover::before { background: rgba(var(--wheel-ring), .3); }
.pit-mini-wheel-btn:focus-visible {
  outline: 2px solid rgba(255,255,255,.85); outline-offset: -3px;
}
.pit-mini-wheel-btn:disabled { cursor: default; pointer-events: none; }
@keyframes pit-wheel-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(var(--wheel-ring), .42); }
  65% { box-shadow: 0 0 0 9px rgba(var(--wheel-ring), 0); }
}

.pit-mini-wheel { fill: #15181d; stroke: #454b55; stroke-width: 2; }
.pit-mini-wheel .rim { fill: #8e949e; stroke: none; }
.pit-mini-old-wheel { fill: #1d1a18; stroke: #575048; }
.pit-mini-old-wheel .rim { fill: #7c7468; }
.pit-mini-new-wheel { fill: #101318; stroke: #748c55; }
.pit-mini-new-wheel .rim { fill: var(--good); }
.pit-mini-hub {
  fill: #10141a; stroke: #59616c; stroke-width: 2; opacity: .25;
  transition: opacity .22s, fill .22s, stroke .22s;
}
.pit-mini-corner[data-state="removed"] .pit-mini-hub { opacity: 1; }
.pit-mini-corner[data-state="new"] .pit-mini-hub { opacity: .2; }
.pit-mini[data-stage="fit"] .pit-mini-corner[data-state="removed"] .pit-mini-hub {
  animation: pit-hub-pulse 1.5s infinite;
}
@keyframes pit-hub-pulse {
  0%, 100% { fill: #10141a; stroke: #59616c; }
  50% { fill: rgba(182,255,92,.24); stroke: var(--good); }
}
.pit-mini-old-wheel, .pit-mini-new-wheel {
  transform-box: fill-box; transform-origin: center;
}
.pit-mini-old-wheel {
  transition: transform .38s var(--ease), opacity .26s ease;
}
.pit-mini-new-wheel {
  opacity: 0;
  transform: translate(var(--wx), var(--wy)) rotate(var(--rot)) scale(.72);
  transition: transform .42s var(--ease), opacity .26s ease;
}
.pit-mini-corner[data-state="removed"] .pit-mini-old-wheel,
.pit-mini-corner[data-state="new"] .pit-mini-old-wheel {
  opacity: 0;
  transform: translate(var(--wx), var(--wy)) rotate(var(--rot)) scale(.72);
}
.pit-mini-corner[data-state="new"] .pit-mini-new-wheel { opacity: 1; transform: none; }

